-- Australia Graphic Designer profile.
-- Current OSCA 242332 is exact for the canonical title.
-- OSCA correspondence to ANZSCO 2022 232411 is partial, so legacy labour data is contextual only.

update public.courses_au set
 official_course_url='https://www.rmit.edu.au/study-with-us/levels-of-study/undergraduate-study/bachelor-degrees/bp115',
 official_url_status='verified',official_url_checked_at=now(),official_url_source='RMIT current Bachelor of Graphic Design page, CRICOS 117452M, verified 2026-08-09'
where institution_id='rmit-university' and course_code='117452M';

update public.courses_au set
 official_course_url='https://www.swinburne.edu.au/course/undergraduate/bachelor-of-design-communication-design-honours/',
 official_url_status='verified',official_url_checked_at=now(),official_url_source='Swinburne current Communication Design Honours page, CRICOS 079130D, verified 2026-08-09'
where institution_id='swinburne-university-of-technology' and course_code='079130D';

insert into public.country_occupation_profiles (profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at) values ('AU:graphic-designer','AU','graphic-designer','Graphic Designer','OSCA','2024 v1.0','2423','AUD',false,'No statutory registration; VETASSESS skills assessment for ANZSCO 232411 is migration-specific','https://www.vetassess.com.au/check-my-occupation/professional-occupations/graphic-designer','profile_ready','2026-08-09',now()) on conflict (profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now();

insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values ('AU:graphic-designer','2026-05-01',null,null,null,null,1852,null,null,null,null,441,'2026-05-01',-7.68,9.86,18.96,0,0,5,0,13,0,5,0,5,28,'career-opportunity-v1','provisional',jsonb_build_object('classification_scope','Current OSCA 242332 Graphic Designer is an exact canonical title. ABS correspondence maps it partially to ANZSCO 2022 232411 Graphic Designer, so current-OSCA and older ANZSCO statistical scopes are not treated as one-to-one.','labour_scope','Primary employment, demographics and earnings are null because the JSA labour profile is ANZSCO-based and the current OSCA correspondence is partial.','legacy_232411_context',jsonb_build_object('employment_total',27500,'part_time_share_pct',37,'female_share_pct',59,'median_age',37,'average_full_time_hours',41,'median_weekly_earnings_aud',null,'scope','Legacy JSA ANZSCO 232411 Graphic Designer context only'),'vacancy_scope','Broader ANZSCO 2324 vacancies were 441 in May 2026 versus 477.66667 in May 2025, about -7.68% year on year; no exact vacancy intensity or trend credit.','projection_scope','Broader ANZSCO 2324 projections are +9.86% to 2030 and +18.96% to 2035; partial growth credit only.','shortage_note','JSA 2025 OSL records current OSCA 242332 Graphic Designer as No Shortage nationally.','visa_basis','VETASSESS assesses ANZSCO 232411 Graphic Designer as Group B, but the current Core Skills Occupation List in the in-force Subclass 186 instrument does not list 232411, so visa credit is zero.','entry_level_basis','RMIT Bachelor of Graphic Design 117452M and Swinburne Bachelor of Design (Communication Design) (Honours) 079130D are current on-campus international study routes with direct graphic and communication design curricula.','score_note','The score deliberately does not convert a migration skills-assessment service or broader ANZSCO labour series into exact current-OSCA labour or visa evidence.'),'2026-08-09') on conflict (profile_key,as_of_date) do update set employment_total=excluded.employment_total,median_weekly_earnings=excluded.median_weekly_earnings,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,all_occupations_median_weekly=excluded.all_occupations_median_weekly,part_time_share_pct=excluded.part_time_share_pct,female_share_pct=excluded.female_share_pct,median_age=excluded.median_age,average_full_time_hours=excluded.average_full_time_hours,vacancies_three_month_avg=excluded.vacancies_three_month_avg,vacancy_period=excluded.vacancy_period,vacancy_yoy_pct=excluded.vacancy_yoy_pct,employment_growth_5y_pct=excluded.employment_growth_5y_pct,employment_growth_10y_pct=excluded.employment_growth_10y_pct,shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;

